) AS v(id, payload, headers, aula, source, ip, received_at, created_at)
WHERE NOT EXISTS (
  SELECT 1 FROM public.cpl_inlead_hooks h
  WHERE h.payload->>'code' = (v.payload::jsonb)->>'code'
    AND h.aula = v.aula
);

-- ETAPA 2: UPDATE existentes incompletos (CSV tem mais respostas)
UPDATE public.cpl_inlead_hooks h
SET payload = (v.payload_completo)::jsonb,
